// Normalise the incoming task + optional overrides.
const body = $input.first().json.body || $input.first().json || {};
const task = (body.task || body.query || '').toString().trim();
if (!task) {
  throw new Error("'task' is required in the webhook body");
}
return [{
  json: {
    task,
    requested_by: body.requested_by || 'n8n',
    trace_hint:   body.trace_hint   || '',
    poll_max:     body.poll_max     || 180,
    poll_every_s: body.poll_every_s || 5
  }
}];

// Remember the execution_id + seed the poll counter.
const start = $input.first().json;
return [{
  json: {
    execution_id: start.execution_id,
    workflow_id:  start.workflow_id,
    stream_url:   start.stream_url,
    status:       start.status,
    poll_count:   0,
    poll_max:     $('Normalise Inputs').first().json.poll_max,
    poll_every_s: $('Normalise Inputs').first().json.poll_every_s
  }
}];

// Merge the latest status with the polling state from upstream.
const status = $input.first().json;
const seed   = $('Seed Poll State').first().json;
const count  = (seed.poll_count || 0) + 1;
const done   = ['completed','complete','success','failed','error','cancelled'].includes(
  (status.status || '').toLowerCase()
);
const exceeded = count >= seed.poll_max;
return [{
  json: {
    ...seed,
    ...status,
    poll_count:    count,
    done,
    exceeded,
    proceed:       done || exceeded
  }
}];

// Pick the summariser output (last node) from the full state.
const st = $input.first().json;
const nodes = st.nodes || st.node_outputs || {};
const summary = nodes.summariser?.output || nodes.summariser || null;
const debugger_ = nodes.debugger?.output || nodes.debugger || null;
const critic = nodes.adversarial_critic?.output || nodes.adversarial_critic || null;
return [{
  json: {
    execution_id:    st.execution_id,
    workflow_id:     st.workflow_id,
    status:          st.status,
    ended_reason:    st.exceeded ? 'poll_budget_exceeded' : 'orchestrator_finished',
    summary,
    tests_passed:    debugger_?.tests_pass ?? null,
    debug_rounds:    debugger_?.rounds_used ?? null,
    critic_verdict:  critic?.verdict ?? null,
    critic_findings: critic?.findings ?? [],
    lessons_seen:    $('Pre-flight: Lessons Lookup').first().json?.result?.data?.results || []
  }
}];
